<script setup lang="ts">
import { ArrowUpRight, Plus, Radar, X } from 'lucide-vue-next'
definePageMeta({ layout: 'app' })
const api = useApi(); const open = ref(false); const saving = ref(false)
const { data: assets, refresh } = await useAsyncData('portal-assets', () => api.request<any[]>('/portal/assets').catch(() => []))
const form = reactive({ name: '', location: 'Houston, TX', lengthKm: 10, diameterMm: 323.9, wallMm: 8.2, maopKpa: 6900, product: 'Natural gas liquids', grade: 'API 5L X52', installYear: 2015 })
async function create() { saving.value = true; try { await api.request('/portal/assets', { method: 'POST', body: form }); open.value = false; await refresh() } finally { saving.value = false } }
</script>
<template>
  <div>
    <PortalHeader><template #eyebrow>Asset register</template><template #title>Every mile, one record.</template><template #subtitle>Pipelines, mains and laterals connected to inspection, risk and work history.</template><template #actions><button class="btn btn-dark !min-h-9 !px-3 !text-[10px]" @click="open = true"><Plus :size="13" /> Add asset</button></template></PortalHeader>
    <div class="grid gap-4 lg:grid-cols-2 xl:grid-cols-3">
      <article v-for="asset in (assets || [])" :key="asset._id" class="overflow-hidden rounded-xl border border-ink/12 bg-bone">
        <div class="relative h-36 overflow-hidden"><PhotoImage :name="asset.product?.includes('water') ? 'water-utility' : 'oil-pipeline'" :alt="asset.name" sizes="(min-width:1024px) 30vw, 100vw" class="size-full object-cover opacity-75" /><div class="absolute inset-0 bg-gradient-to-t from-ink/70 to-transparent" /><div class="absolute bottom-3 left-4 right-4 flex items-end justify-between"><div><p class="font-mono text-[8px] uppercase tracking-[.1em] text-bone/60">{{ asset.location }}</p><p class="font-display text-[21px] text-bone">{{ asset.name }}</p></div><span class="rounded-full bg-bone/15 px-2 py-1 font-mono text-[8px] uppercase text-bone backdrop-blur">{{ asset.health }} health</span></div></div>
        <div class="p-4"><div class="grid grid-cols-3 gap-2"><div><p class="font-mono text-[8px] uppercase tracking-[.06em] text-ink/35">Length</p><p class="mt-0.5 text-[12.5px]">{{ asset.lengthKm }} km</p></div><div><p class="font-mono text-[8px] uppercase tracking-[.06em] text-ink/35">OD</p><p class="mt-0.5 text-[12.5px]">{{ asset.diameterMm }} mm</p></div><div><p class="font-mono text-[8px] uppercase tracking-[.06em] text-ink/35">MAOP</p><p class="mt-0.5 text-[12.5px]">{{ asset.maopKpa }} kPa</p></div></div><div class="mt-4 flex items-center justify-between border-t border-ink/10 pt-3"><span class="font-mono text-[9px] text-ink/35">Last run {{ shortDate(asset.lastRunAt) }}</span><NuxtLink to="/app/inspections" class="inline-flex items-center gap-1 font-mono text-[9px] uppercase tracking-[.06em] text-signal-deep">Inspect <ArrowUpRight :size="11" /></NuxtLink></div></div>
      </article>
      <button class="flex min-h-64 flex-col items-center justify-center rounded-xl border border-dashed border-ink/20 text-ink/40 transition-colors hover:border-ink/40 hover:text-ink" @click="open = true"><Plus :size="20" /><span class="mt-2 text-[12px]">Add another asset</span></button>
    </div>
    <div v-if="open" class="fixed inset-0 z-[70] flex items-start justify-center overflow-y-auto bg-ink/45 p-4 backdrop-blur-sm md:items-center" @click.self="open = false"><div class="w-full max-w-xl rounded-2xl bg-bone p-5 shadow-2xl md:p-7"><div class="flex items-start justify-between"><div><p class="label-mono text-signal-deep">New asset</p><h2 class="mt-1 font-display text-[28px]">Register a line</h2></div><button class="text-ink/40" @click="open = false"><X :size="18" /></button></div><form class="mt-5 grid gap-4 sm:grid-cols-2" @submit.prevent="create"><div class="sm:col-span-2"><label class="field-label">Asset name</label><input v-model="form.name" required class="field" placeholder="e.g. Gulf Coast Trunk 12"></div><div><label class="field-label">Location</label><input v-model="form.location" class="field"></div><div><label class="field-label">Product</label><input v-model="form.product" class="field"></div><div><label class="field-label">Length (km)</label><input v-model.number="form.lengthKm" type="number" class="field"></div><div><label class="field-label">Outside diameter (mm)</label><input v-model.number="form.diameterMm" type="number" class="field"></div><div><label class="field-label">Wall (mm)</label><input v-model.number="form.wallMm" type="number" step="0.1" class="field"></div><div><label class="field-label">MAOP (kPa)</label><input v-model.number="form.maopKpa" type="number" class="field"></div><div class="sm:col-span-2 flex justify-end gap-2 pt-2"><button type="button" class="btn btn-outline" @click="open = false">Cancel</button><button class="btn btn-dark" :disabled="saving">{{ saving ? 'Saving…' : 'Add asset' }}</button></div></form></div></div>
  </div>
</template>
